from pathlib import Path
from PIL import Image,ImageDraw,ImageFont
import json,hashlib
root=Path('prototypes/reconstruction-c');ref=Image.open(root/'reference.jpg').convert('RGB');proto=Image.open(root/'browser-1280-visible.png').convert('RGB');font=ImageFont.truetype('/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf',14)
# Both images are unscaled native1280×640. Crops only translate a component within the comparison;
# no independent resizing, colour alteration or perspective correction is applied.
crops={
 'knob':((1030,238,1072,291),(1014,244,1056,297)),
 'fader':((609,84,651,207),(611,84,653,207)),
 'switch':((60,95,142,122),(63,95,145,122)),
 'screen':((769,109,912,155),(769,109,912,155)),
 'header':((27,1,1250,51),(27,1,1250,51)),
 'cheek':((0,0,32,640),(0,0,32,640)),
 'keyboard':((23,486,1258,635),(23,486,1258,635)),
 'wheel':((52,510,96,623),(52,510,96,623)),
 'envelope':((43,220,522,314),(43,220,522,314)),
}
manifest=[]
for name,(a,b) in crops.items():
 left=ref.crop(a);right=proto.crop(b);left.save(root/f'reference-{name}.png');right.save(root/f'prototype-{name}.png');assert left.size==right.size
 zoom=2 if name not in ['header','cheek','keyboard','envelope'] else 1
 w=max(260,left.width*zoom);h=left.height*zoom
 canvas=Image.new('RGB',(w*2+36,h+58),'#0b0e0c');d=ImageDraw.Draw(canvas);d.text((10,9),'Original mockup',font=font,fill='#cad8cf');d.text((w+28,9),'Browser prototype C',font=font,fill='#cad8cf')
 canvas.paste(left.resize((left.width*zoom,left.height*zoom)),(10,38));canvas.paste(right.resize((right.width*zoom,right.height*zoom)),(w+28,38));canvas.save(root/f'compare-{name}.png');manifest.append({'name':name,'referenceCrop':a,'prototypeCrop':b,'nativeSize':left.size,'displayZoomBoth':zoom,'sameScale':True,'independentResize':False,'colourCorrection':False})
full=Image.new('RGB',(2560,674),'#0b0e0c');full.paste(ref,(0,34));full.paste(proto,(1280,34));d=ImageDraw.Draw(full);d.text((16,8),'Original reference • native1280×640',font=font,fill='#cad8cf');d.text((1296,8),'Isolated browser prototype • native1280×640',font=font,fill='#cad8cf');full.save(root/'compare-cabinet.png')
(root/'comparison-scale.json').write_text(json.dumps({'referenceSha256':hashlib.sha256((root/'reference.jpg').read_bytes()).hexdigest(),'referenceDimensions':ref.size,'browserDimensions':proto.size,'componentComparisons':manifest,'realKeyboardPhoto':{'source':'User-provided Behringer MS-5 photograph in conversation; secondary product reference https://www.thomann.de/de/behringer_ms_5.htm','localPhotoAvailable':False,'inspection':'Qualitative stepped key/black-key seating comparison from supplied conversation photograph; no new pixel measurements or photo capture claimed.','networkLimitation':'Secondary image download was blocked; no proxy bypass attempted.'}},indent=2)+'\n')
html='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>GRIMISS — hardware prototype C review</title><style>*{box-sizing:border-box}body{margin:0;padding:26px;background:#090d0b;color:#cbd9d0;font:700 15px system-ui,Arial,sans-serif;line-height:1.55}main{max-width:1500px;margin:auto}h1,h2{color:#62d9c4}h1{font-size:25px}h2{font-size:19px;margin-top:32px}a{color:#79dfcf}img{display:block;max-width:100%;border:1px solid #344b3e;background:#030805}figure{margin:16px 0}figcaption,.note{font-size:13px;color:#8da99a}table{border-collapse:collapse;width:100%;font-size:13px}td,th{border:1px solid #2e493a;padding:9px;text-align:left;vertical-align:top}.links{display:flex;gap:18px;flex-wrap:wrap}.banner{padding:13px;border:1px solid #5c815d;background:#101e14}.wide{overflow:auto}.wide img{max-width:none}button{background:#173327;color:#cbe9dc;border:1px solid #53836a;padding:8px;font:inherit}.diagnostic{padding:14px;background:#101510;border:1px solid #79623f}code{color:#a8ddc3}</style><main><h1>Hardware reconstruction C — isolated approval prototype</h1><p class="banner">Review checkpoint B. This is a separate browser-rendered material, cabinet and key-geometry prototype. Its controls demonstrate local interaction only: there is no synthesizer audio, MIDI or patch engine attached. The playable synth and its DSP are not modified by this prototype. Full visual rollout awaits approval.</p><p class="links"><a href="board.html">Open interactive prototype</a><a href="browser-1920-visible.png">1920 × 1080 / keys visible</a><a href="browser-1920-hidden.png">1920 × 1080 / keys hidden</a><a href="browser-1600-visible.png">1600 × 900 / keys visible</a><a href="browser-1600-hidden.png">1600 × 900 / keys hidden</a><a href="verification.json">Browser checks</a></p><h2>Cabinet and overall proportion comparison</h2><p>Both source images are native1280 × 640. Open the full-resolution image to inspect them at1:1; the page may scale the combined image uniformly to fit your window. Section positions preserve the approved envelope/filter/EQ amendments. The prototype demonstrates a coherent full cabinet around isolated component samples, not a replacement functional interface.</p><a href="compare-cabinet.png"><img src="compare-cabinet.png" alt="Original mockup and actual browser prototype, both at equal native scale"></a><h2>Component comparisons — equal native scale</h2><p>Left: supplied original mockup. Right: actual Chromium screenshot. Crop dimensions and identical display zoom are recorded in <a href="comparison-scale.json">comparison-scale.json</a>. No independent scaling, colour correction or perspective adjustment has been applied.</p>'''
for name in ['knob','fader','switch','screen','wheel','header','cheek']:
 html+=f'<figure><h3>{name.title()}</h3><a href="compare-{name}.png"><img src="compare-{name}.png" alt="Equal-scale {name} comparison"></a></figure>'
html+='''<h2>Keyboard — normal construction and stepped-key diagnostic</h2><p>The required three-octave range remains C3–C6:22 white keys and15 black keys. The bank fills the953-unit opening. White keys now use actual notched silhouettes; black keys sit within those cut-outs and have raised top, side and front faces. E–F and B–C retain the correct no-black-key gaps. No note names are printed on the key faces.</p><figure><a href="compare-keyboard.png"><img src="compare-keyboard.png" alt="Equal-native-scale mockup and prototype keyboard housing"></a><figcaption>Both complete key housings use1235 ×149 native pixels. The mockup depicts more white-key fronts than the approved37-note range; consequently, exact per-key width matching and full housing occupancy cannot both be reproduced. This prototype preserves the user-approved range and full-width occupancy, not an invented extra key range.</figcaption></figure><figure class="diagnostic"><h3>Diagnostic only — black-key bodies hidden</h3><img src="browser-white-silhouettes-diagnostic.png" alt="Diagnostic exposes physical notches in the white key silhouettes"><figcaption>This separate browser capture temporarily hides black keys to expose the real white-key cut-outs. The normal prototype retains all black keys. Hit tests verify that every white-key notch is excluded from that white key's pointer region.</figcaption></figure><h2>Comparison with a physical synthesizer keyboard</h2><p>The user-provided Behringer MS-5 photograph supplies the physical construction reference: narrow upper white-key stems, full-width white fronts, black-key bodies seated between those stems, and uninterrupted E–F/B–C boundaries. Prototype C uses these stepped silhouettes and raised black-key faces instead of placing black rectangles over continuous white rectangles.</p><p class="note">The real photograph was supplied earlier in the conversation. A new local copy was unavailable; the secondary product-image download was blocked by the environment policy. No equal-scale photographic measurement or new photo capture is claimed. <a href="https://www.thomann.de/de/behringer_ms_5.htm" target="_blank" rel="noreferrer">Physical MS-5 reference source</a>. Colours remain GRIMISS charcoal/teal/magenta/amber; the MS-5 palette is not adopted.</p><h2>What remains intentionally different</h2><table><tr><th>Reference or approved requirement</th><th>Prototype decision</th></tr><tr><td>Near-black enclosure with integrated flat housings</td><td>22-unit graphite side housings, restrained edge highlights, one recessed deck and physical keyboard divider; no tubular rails.</td></tr><tr><td>Compact reference rotary and fader geometry</td><td>28-unit rotaries with thin pointers/active arcs; compact23 ×11 caps over99-unit recessed slots. Enlarged cutoff remains an intentional approved exception.</td></tr><tr><td>Approved filter/amp envelope, filter and EQ amendments</td><td>420-unit envelope widths,510-unit filter and256 ×94 EQ. Prototype EQ demonstrates only material/control appearance; the working four-control EQ and response/detail view remain intact in the playable synth.</td></tr><tr><td>Additional functional controls and graphs</td><td>This isolated prototype does not substitute its simplified sample controls for working features. Rollout must retain original nodes/bindings and use approved compact/detail arrangements where needed.</td></tr><tr><td>Original mockup keyboard shows more fronts</td><td>Approved37-note C3–C6 bank retained across the full housing. Geometry compromise is explicitly documented above.</td></tr></table><h2>Browser validation</h2><p>Chromium captures cover1920 ×1080 and1600 ×900 with keyboard visible and hidden, plus a native1280 ×640 capture. Checks cover bounds/overflow, all37note identities, notched pointer hit regions, local knob/fader/switch interaction, key press/release and local pitch-wheel spring return. These checks do not claim audio, MIDI or physical-device validation.</p><p>Rebuild: <code>node prototypes/reconstruction-c/build.cjs</code>. Capture/check: <code>node prototypes/reconstruction-c/verify.cjs</code>; <code>node prototypes/reconstruction-c/components.cjs</code>; <code>python prototypes/reconstruction-c/compare.py</code>.</p></main></html>'''
(root/'index.html').write_text(html)
